type Row = Record<string, any>;
type Field = { key: string; label: string; type?: string; placeholder?: string; options?: { value: string; label: string }[]; choices?:ChoiceSource; value?: any; optional?: boolean; max?: number; help?: string };
type Modal = { title: string; description?: string; action?: string; fields?: Field[]; args?: Row; submit?: string; content?: React.ReactNode };
const labels: Row = { pending: 'Awaiting connection', connected: 'Connected', revoked: 'Disconnected', example: 'Example agent', queued: 'Waiting for agent', working: 'In progress', needs_input: 'Needs input', completed: 'Completed', declined: 'Declined', accepted: 'Accepted', active: 'Active' };
const date = (value?: string) => value ? new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' }).format(new Date(value)) : 'Not yet';
