function Badge({ status, text }: { status: string; text?: string }) { return <span className={`badge ${status}`}>{text || labels[status] || status}</span>; }
function Empty({ icon: Icon = Layers3, title, children, action }: { icon?: any; title: string; children: React.ReactNode; action?: React.ReactNode }) { return <div className="empty"><Icon size={28} strokeWidth={1.5} /><h3>{title}</h3><p>{children}</p>{action}</div>; }
function FormDialog({ modal, onClose, onSubmit }: { modal: Modal; onClose: () => void; onSubmit: (a: Row) => Promise<void> }) {
  const retry = useRef<{signature:string;id:string}|null>(null);
  const ref = useRef<HTMLDialogElement>(null), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const [choiceLoading,setChoiceLoading]=useState<Row>({});
  useEffect(() => {
    const trigger=document.activeElement instanceof HTMLElement?document.activeElement:null;
    ref.current?.showModal();
    return()=>queueMicrotask(()=>{
      if(document.querySelector('dialog[open]'))return;
      if(trigger?.isConnected&&!trigger.matches(':disabled'))trigger.focus();
      else {const heading=document.querySelector<HTMLElement>('#workspace-main h1')||document.getElementById('workspace-main');if(heading){heading.tabIndex=-1;heading.focus();}}
    });
  }, []);
  return <dialog ref={ref} onCancel={e => { if (busy) e.preventDefault(); else onClose(); }} aria-labelledby="dialog-title" aria-describedby={modal.description?'dialog-description':undefined}>
    <div className="dialog-heading"><div><span className="eyebrow">ACCORD</span><h2 id="dialog-title">{modal.title}</h2></div><button className="icon-button" aria-label="Close dialog" disabled={busy} onClick={onClose}><X size={20} /></button></div>
    {modal.description && <p id="dialog-description" className="dialog-description">{modal.description}</p>}{modal.content}
    {modal.action && <form onSubmit={async e => { e.preventDefault(); setBusy(true); setError(''); const data = new FormData(e.currentTarget), a: Row = { ...modal.args }; try { for (const f of modal.fields || []) a[f.key] = f.type === 'checkbox' ? data.get(f.key) === 'on' : data.get(f.key); if (a.expires_at) a.expires_at = normalizePermissionExpiry(a.expires_at, modal.fields?.find(f => f.key === 'expires_at')?.type || 'date'); if(['send_instruction','propose_context_change','grant_authority','create_space','add_agent','add_source'].includes(modal.action!)){const signature=JSON.stringify(a);if(retry.current?.signature!==signature)retry.current={signature,id:crypto.randomUUID()};a.request_id=retry.current.id;} await onSubmit(a); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }}>
      {(modal.fields || []).map(f => <div className={`form-field ${f.type === 'checkbox' ? 'check-field' : ''}`} key={f.key}>
        {f.type === 'checkbox' ? <label><input type="checkbox" name={f.key} aria-describedby={f.help?`help-${f.key}`:undefined} defaultChecked={!!f.value} />{f.label}</label> : <><label htmlFor={`field-${f.key}`}>{f.label}{f.optional && <span> · optional</span>}</label>
          {f.type === 'textarea' ? <textarea id={`field-${f.key}`} name={f.key} aria-describedby={f.help?`help-${f.key}`:undefined} defaultValue={f.value || ''} placeholder={f.placeholder} maxLength={f.max || 5000} required={!f.optional} rows={4} /> : f.choices ? <PagedSelect id={`field-${f.key}`} name={f.key} label={f.label} source={f.choices} optional={f.optional} initialValue={f.value||''} disabled={busy} onLoading={loading=>setChoiceLoading(previous=>({...previous,[f.key]:loading}))}/> : f.options ? <select id={`field-${f.key}`} name={f.key} aria-describedby={f.help?`help-${f.key}`:undefined} defaultValue={f.value || ''} required={!f.optional}><option value="">{f.optional ? 'No source selected' : 'Choose one'}</option>{f.options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}</select> : <input id={`field-${f.key}`} name={f.key} aria-describedby={f.help?`help-${f.key}`:undefined} type={f.type || 'text'} step={f.type === 'datetime-local' ? 1 : undefined} defaultValue={f.value || ''} maxLength={f.max || 120} required={!f.optional} placeholder={f.placeholder} />}</>}
        {f.help && <p id={`help-${f.key}`} className="field-help">{f.help}</p>}
      </div>)}
      {error && <p className="error" role="alert">{error}</p>}
      <div className="dialog-actions"><button type="button" className="button secondary" disabled={busy} onClick={onClose}>Cancel</button><button className="button primary" disabled={busy||Object.values(choiceLoading).some(Boolean)}>{busy ? 'Saving…' : modal.submit || 'Save'}</button></div>
    </form>}
  </dialog>;
}

