  const myAvailable = available.filter((a: Row) => a.owner_id === user.id);
  const sendingGrants = (kind: string) => grants.filter((g: Row) => owned(g.from_agent) && g[kind]);
  const grantOptions = (kind: string) => sendingGrants(kind).map((g: Row) => ({ value: g.id, label: `${agentName(g.from_agent)} → ${agentName(g.to_agent)}` }));
